CREATE TABLE IF NOT EXISTS admin_integration_connections (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider_key VARCHAR(80) NOT NULL UNIQUE,environment ENUM('test','live') NOT NULL DEFAULT 'test',enabled TINYINT(1) NOT NULL DEFAULT 1,values_json JSON NULL,secrets_encrypted MEDIUMBLOB NULL,last_test_ok TINYINT(1) NULL,last_test_message VARCHAR(255) NULL,last_tested_at DATETIME NULL,updated_by INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_platform_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value JSON NOT NULL,updated_by INT UNSIGNED NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_account_levels (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,uuid CHAR(36) NOT NULL UNIQUE,account_type ENUM('individual','business') NOT NULL,rank TINYINT UNSIGNED NOT NULL,name VARCHAR(40) NOT NULL,requirement VARCHAR(191) NULL,deposit_single DECIMAL(18,2) NOT NULL DEFAULT 0,deposit_daily DECIMAL(18,2) NOT NULL DEFAULT 0,withdraw_single DECIMAL(18,2) NOT NULL DEFAULT 0,withdraw_daily DECIMAL(18,2) NOT NULL DEFAULT 0,transfer_single DECIMAL(18,2) NOT NULL DEFAULT 0,transfer_daily DECIMAL(18,2) NOT NULL DEFAULT 0,max_balance DECIMAL(18,2) NULL,fee_percent DECIMAL(5,2) NOT NULL DEFAULT 0,api_access TINYINT(1) NOT NULL DEFAULT 0,payment_links TINYINT(1) NOT NULL DEFAULT 0,bulk_transfers TINYINT(1) NOT NULL DEFAULT 0,updated_by INT UNSIGNED NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY account_level_rank(account_type,rank),FOREIGN KEY(updated_by) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_level_changes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,level_uuid CHAR(36) NOT NULL,admin_user_id INT UNSIGNED NULL,summary VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_user_id) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB;
